from lib import *
R=[]
R.append((6460699,{
"es":L("Ensalada de verano como plato principal","¡Deje que esta abundante ensalada, con bistec de solomillo a la parrilla, muchas verduras y una vinagreta con ajo, sea la protagonista de su mesa este verano!\n\nEncuentre esta receta y más en nuestro libro de cocina, Complete Month of Meals, donde puede combinar recetas a su gusto para planificar sus comidas fácilmente.","4","3 onzas de carne + 1 ½ cucharadas de aderezo + 1 ⅓ tazas de verduras + 1 taza de hojas verdes",
["1 taza de maíz congelado","4 cucharaditas de aceite de canola","3 dientes de ajo (en rodajas)","1/4 taza de vinagre de vino tinto","1 cucharada de mostaza Dijon","1/4 cucharadita de pimienta negra (al gusto)","1/4 cucharadita de azúcar","12 onzas de solomillo a la parrilla","1 taza de papas cocidas (cortadas en cubos)","1 taza de cebollín (cebolla de verdeo) (en rodajas)","1/2 taza de zanahorias (en rodajas finas)","1 taza de pimiento rojo (en cubitos)","1 taza de pimiento verde (en cubitos)","4 tazas de hojas verdes tiernas para ensalada"],
["Cocine el maíz según las instrucciones del paquete.","En una cacerola pequeña, caliente el aceite; agregue el ajo y saltee hasta que se dore.","Retire del fuego y deje enfriar; cuele y reserve el aceite; deseche el ajo.","En un tazón grande, combine el aceite reservado, el vinagre, la mostaza, la pimienta y el azúcar. Agregue 1/2 cucharadita de sal, si lo desea.","Mezcle la preparación de aceite con el maíz, el solomillo, las papas, el cebollín, las zanahorias y ambos tipos de pimientos. Mezcle bien, tape y refrigere.","Sirva en un tazón forrado con las hojas verdes para ensalada."]),
"ar":L("سلطة صيفية كطبق رئيسي","دع هذه السلطة الدسمة، المكوّنة من شرائح لحم السيرلوين المشوي وكمية وفيرة من الخضار وصلصة الفينيغريت بالثوم، تتصدر مائدتك هذا الصيف!\n\nستجد هذه الوصفة والمزيد في كتاب الطبخ الخاص بنا، Complete Month of Meals، حيث يمكنك الجمع بين الوصفات بحسب رغبتك لتسهيل تخطيط الوجبات!","4","3 أونصات لحم + 1½ ملعقة كبيرة صلصة + 1⅓ كوب خضار + 1 كوب أوراق خضراء",
["1 كوب ذرة مجمدة","4 ملاعق صغيرة زيت كانولا","3 فص ثوم (مقطع شرائح)","¼ كوب خل النبيذ الأحمر","1 ملعقة كبيرة خردل ديجون","¼ ملعقة صغيرة فلفل أسود (حسب الرغبة)","¼ ملعقة صغيرة سكر","12 أونصة لحم سيرلوين مشوي","1 كوب بطاطس مسلوقة (مقطعة مكعبات)","1 كوب بصل أخضر (مقطع شرائح)","½ كوب جزر (مقطع شرائح رفيعة)","1 كوب فلفل رومي أحمر (مقطع مكعبات)","1 كوب فلفل رومي أخضر (مقطع مكعبات)","4 أكواب أوراق سلطة صغيرة"],
["اطهِ الذرة وفق تعليمات العبوة.","في قدر صغير، سخّن الزيت؛ أضف الثوم وقلّبه حتى يحمرّ.","ارفعه عن النار واتركه يبرد؛ صفِّه واحتفظ بالزيت وتخلص من الثوم.","في وعاء كبير، اخلط الزيت المحتفظ به والخل والخردل والفلفل والسكر. أضف ½ ملعقة صغيرة من الملح إن رغبت.","اخلط مزيج الزيت مع الذرة واللحم والبطاطس والبصل الأخضر والجزر ونوعي الفلفل. امزج جيدًا وغطِّه وضعه في الثلاجة.","قدّمه في وعاء مبطّن بأوراق السلطة."])}))
R.append((6460875,{
"es":L("Chiffon de limón con frutos rojos frescos","La autora Barbara Seelig-Brown dice: \"Este postre dulce y ácido es muy refrescante y se derrite en la boca. Es lo bastante ligero para disfrutarlo sin culpa. Incluir fruta en un postre ayuda a reducir las calorías y la grasa. Puede prepararlo uno o dos días antes de una fiesta y quedará aún mejor una vez que se mezclen los sabores\".","6","1/2 taza",
["1/3 taza de jugo de limón (aproximadamente 2 limones grandes)","1/2 taza de sustituto de azúcar bajo en calorías","4 huevos grandes","3 tazas de frutos rojos frescos (como fresas, arándanos azules y moras)"],
["Coloque el jugo de limón y el sustituto de azúcar en una cacerola. Caliente y revuelva hasta que el azúcar se disuelva. Retire del fuego.","Rompa los huevos en un tazón y bata bien. Vierta lentamente la mezcla de limón y azúcar sobre los huevos mientras bate. Bata durante 1 minuto y luego regrese la mezcla de huevo a la cacerola.","Bata y cocine a fuego bajo a medio durante varios minutos, hasta que la mezcla de huevo espese. (Cuanto más bata, más ligera quedará la mezcla). Esto tomará de 2 a 5 minutos, según su equipo. La mezcla está lista para retirarse del fuego cuando cubre el dorso de una cuchara.","Refrigere durante una hora o más. Se espesará más al enfriarse.","Coloque un poco del chiffon de limón en una copa o un tazón para postre y agregue los frutos rojos encima con una cuchara. Alterne capas de crema de limón y frutos rojos. Termine con frutos rojos encima."]),
"ar":L("شيفون الليمون مع التوت الطازج","تقول المؤلفة باربرا سيليغ-براون: \"هذه الحلوى الحلوة الحامضة اللذيذة منعشة جدًا وتذوب في الفم. وهي خفيفة بما يكفي للاستمتاع بها دون شعور بالذنب. إن إضافة الفاكهة إلى الحلوى تساعد على تقليل السعرات الحرارية والدهون. يمكنك تحضيرها قبل الحفلة بيوم أو يومين، وستكون أطيب حين تمتزج النكهات\".","6","½ كوب",
["⅓ كوب عصير ليمون (من نحو 2 ليمونة كبيرة)","½ كوب بديل سكر قليل السعرات","4 بيضات كبيرة","3 أكواب توت طازج (مثل الفراولة والتوت الأزرق والتوت الأسود)"],
["ضع عصير الليمون وبديل السكر في قدر. سخّنهما وقلّبهما حتى يذوب السكر. ارفعهما عن النار.","اكسر البيض في وعاء واخفقه جيدًا. اسكب خليط الليمون والسكر ببطء على البيض مع الاستمرار في الخفق. اخفق لمدة دقيقة واحدة، ثم أعد خليط البيض إلى القدر.","اخفق واطهِ على نار هادئة إلى متوسطة لعدة دقائق حتى يتكاثف خليط البيض. (كلما زاد الخفق صار الخليط أخف). سيستغرق ذلك من 2 إلى 5 دقائق بحسب أدواتك. يكون الخليط جاهزًا للرفع عن النار عندما يغطي ظهر الملعقة.","ضعه في الثلاجة لمدة ساعة أو أكثر. سيزداد تكاثفًا عند البرودة.","ضع بعضًا من شيفون الليمون في كأس حلوى أو وعاء، ثم وزّع التوت فوقه بالملعقة. بدّل بين طبقات كريمة الليمون والتوت. زيّن الوجه بالتوت."])}))
R.append((6461142,{
"es":L("Nuggets de pollo con salsa de miel y mostaza","Esta receta no solo es deliciosa, sino que además es apta para los riñones. Pruebe una variedad de salsas para mojar, como salsa barbacoa, salsa de curry, mermeladas de fruta o aderezo para ensalada bajo en sodio.","12","3 nuggets + 1 cucharada de salsa",
["3 tazas de hojuelas de maíz","2 cucharadas de leche al 1 %","1 huevo grande","2 cucharaditas de salsa Worcestershire","3 cucharadas de miel","1/2 taza de mayonesa","1 cucharada de mostaza amarilla","1 libra de pechugas de pollo sin hueso ni piel","1 rocío, 0.25 gramos de aceite en aerosol antiadherente"],
["Revuelva la mostaza, la mayonesa, la miel y la salsa Worcestershire en un tazón pequeño. Refrigere la salsa para que se enfríe mientras se cocinan los nuggets.","Precaliente el horno a 400 °F.","Corte la pechuga de pollo en 36 trozos del tamaño de un bocado.","Combine el huevo batido y la leche en un tazón pequeño. Sumerja los trozos de pollo en la mezcla de huevo y luego agítelos en una bolsa con cierre hermético para cubrirlos con las migas de hojuelas de maíz.","Hornee los nuggets en una bandeja para hornear rociada con aceite en aerosol antiadherente durante 15 minutos, hasta que estén cocidos."]),
"ar":L("ناجتس الدجاج مع صلصة الغمس بالعسل والخردل","هذه الوصفة لذيذة، كما أنها مناسبة لمرضى الكلى. جرّب مجموعة متنوعة من صلصات الغمس، مثل صلصة الشواء وصلصة الكاري ومربى الفاكهة أو صلصة السلطة قليلة الصوديوم.","12","3 قطع ناجتس + 1 ملعقة كبيرة صلصة",
["3 أكواب رقائق الذرة (كورن فليكس)","2 ملعقة كبيرة حليب 1%","1 بيضة كبيرة","2 ملعقة صغيرة صلصة ورسترشير","3 ملاعق كبيرة عسل","½ كوب مايونيز","1 ملعقة كبيرة خردل أصفر","1 رطل صدور دجاج بدون عظم وبدون جلد","1 بخّة، 0.25 جرام بخاخ طهي غير لاصق"],
["قلّب الخردل والمايونيز والعسل وصلصة ورسترشير في وعاء صغير. ضع الصلصة في الثلاجة لتبرد إلى أن ينضج الناجتس.","سخّن الفرن مسبقًا إلى 400° فهرنهايت (200° مئوية).","قطّع صدر الدجاج إلى 36 قطعة بحجم اللقمة.","اخلط البيض المخفوق والحليب في وعاء صغير. اغمس قطع الدجاج في خليط البيض ثم رجّها في كيس بسحّاب لتتغطى بفتات رقائق الذرة.","اخبز الناجتس على صينية خبز مرشوشة ببخاخ الطهي غير اللاصق لمدة 15 دقيقة حتى ينضج."])}))
R.append((6461143,{
"ar":L("خبز الموز الخالي من الغلوتين","يمكن أن يكون خبز الموز هذا الخالي من الغلوتين حلوى لطيفة ليوم الحب (عيد العشاق)، وهو خالٍ من الغلوتين! بدلًا من رغيف كبير واحد، يمكنك تحضيره في أربعة قوالب صغيرة للحصول على أرغفة صغيرة يمكن تغليفها وتقديمها كهدايا في عيد الحب.","16","1 شريحة",
["1 بخّة، 0.25 جم بخاخ طهي غير لاصق","4 حبات موز متوسطة (ناضجة جدًا، مهروسة)","2 ملعقة كبيرة زيت زيتون","1 كوب لبن رائب (بتّرميلك) قليل الدسم","2 بياض بيض كبير","1 ملعقة صغيرة خلاصة الفانيلا","¼ كوب محلٍّ قليل السعرات أو خالٍ منها","2 كوب خليط خبز متعدد الاستخدامات خالٍ من الغلوتين","3 ملاعق كبيرة بذور الكتان المطحونة"],
["سخّن الفرن مسبقًا إلى 350 درجة فهرنهايت (175° مئوية). رُشّ قالب رغيف مقاس 8×4 بوصات ببخاخ الطهي.","في وعاء كبير، اخلط الموز والزيت واللبن الرائب وبياض البيض والفانيلا والمحلّي القليل السعرات أو الخالي منها؛ وامزج جيدًا.","أضف خليط الخبز الخالي من الغلوتين وبذور الكتان وامزج حتى يتجانس الخليط. اسكب العجين في قالب الرغيف. اخبز لمدة 30 إلى 35 دقيقة أو حتى يخرج عود الأسنان المغروس في الوسط نظيفًا."])}))
R.append((6461642,{
"es":L("Tiras de pimiento","Información nutricional de las tiras de pimiento","1","1 taza",["1 taza de pimientos"],[]),
"ar":L("شرائح الفلفل الرومي","المعلومات الغذائية لشرائح الفلفل الرومي","1","1 كوب",["1 كوب فلفل رومي"],[])}))
R.append((6461923,{
"es":L("Nueces pecanas, 1/2 onza","Información nutricional de las nueces pecanas","1","1/2 onza",["1/2 onza de nueces pecanas"],[]),
"ar":L("الجوز البقان، ½ أونصة","المعلومات الغذائية للجوز البقان","1","½ أونصة",["½ أونصة جوز بقان"],[])}))
R.append((6461989,{
"es":L("Tofu con salsa de maní, brócolini y quinua","Disfrute del delicioso equilibrio de sabores de esta receta de tofu. El tofu crujiente se baña en una salsa cremosa de maní y se sirve junto con brócolini tierno y quinua esponjosa. Este plato del patrón de alimentación vegano no solo es nutritivo, sino también increíblemente saciante.","4","1/2 taza de quinua cocida, 1 taza de tofu, 1/2 taza de brócolini",
["1 limón verde entero","1 trozo de jengibre fresco de 1 pulgada (pelado y picado)","1/4 taza de mantequilla de maní en polvo","2 cucharadas de agua","1 cucharada de salsa de soya","2 cucharaditas de azúcar morena","21 onzas de tofu extrafirme (escurrido y prensado)","2 cucharaditas de fécula de maíz","1 cucharada de aceite de oliva","2 manojos de brócolini","2 tazas de quinua cocida"],
["Exprima el jugo del limón verde en un tazón pequeño.","Agregue el jengibre, la mantequilla de maní en polvo, el agua, la salsa de soya y el azúcar morena a un tazón. Bata para combinar la salsa.","Precaliente un sartén grande a fuego medio.","Mientras el sartén se calienta, corte el tofu en cubos medianos. Colóquelo en un tazón mediano, espolvoree con la fécula de maíz y mezcle suavemente para cubrirlo.","Cuando el sartén esté caliente, agregue 2 cucharaditas de aceite y mueva para cubrir el fondo. Agregue el tofu y fríalo, volteándolo de vez en cuando, hasta que esté dorado y crujiente, de 5 a 7 minutos. Pase el tofu a un tazón.","Regrese el sartén al fuego medio. Agregue el aceite restante y el brócolini al sartén. Cocine, revolviendo con frecuencia, hasta que esté tierno pero crujiente, de 4 a 5 minutos.","Para servir, divida la quinua, el tofu y el brócolini entre los tazones. Rocíe el tofu con la salsa de maní."]),
"ar":L("توفو بصلصة الفول السوداني مع بروكوليني وكينوا","استمتع بالتوازن اللذيذ للنكهات في وصفة التوفو هذه. يُغطّى التوفو المقرمش بصلصة كريمية من الفول السوداني ويُقدَّم مع البروكوليني الطري والكينوا الهشة. هذا الطبق من النمط الغذائي النباتي ليس مغذيًا فحسب، بل مشبع بشكل رائع.","4","½ كوب كينوا مطهوة، 1 كوب توفو، ½ كوب بروكوليني",
["1 حبة ليمون أخضر","قطعة زنجبيل طازجة بطول 1 بوصة (مقشرة ومفرومة)","¼ كوب زبدة فول سوداني بودرة","2 ملعقة كبيرة ماء","1 ملعقة كبيرة صلصة الصويا","2 ملعقة صغيرة سكر بني","21 أونصة توفو شديد الصلابة (مصفى ومضغوط)","2 ملعقة صغيرة نشا الذرة","1 ملعقة كبيرة زيت زيتون","2 حزمة بروكوليني","2 كوب كينوا مطهوة"],
["اعصر الليمون الأخضر في وعاء صغير.","ضع الزنجبيل وزبدة الفول السوداني البودرة والماء وصلصة الصويا والسكر البني في وعاء. اخفق لمزج الصلصة.","سخّن مقلاة كبيرة على نار متوسطة.","بينما تسخن المقلاة، قطّع التوفو إلى مكعبات متوسطة. ضعه في وعاء متوسط ورشّ عليه نشا الذرة ثم قلّبه برفق ليتغطى.","عندما تسخن المقلاة، أضف 2 ملعقة صغيرة من الزيت وحرّكها لتغطية القاع. أضف التوفو وقلّبه في المقلاة مع تقليبه من حين لآخر حتى يحمرّ ويصبح مقرمشًا، من 5 إلى 7 دقائق. انقل التوفو إلى وعاء.","أعد المقلاة إلى نار متوسطة. أضف باقي الزيت والبروكوليني إلى المقلاة. اطهِ مع التحريك المتكرر حتى يصبح طريًا ومقرمشًا، من 4 إلى 5 دقائق.","للتقديم، وزّع الكينوا والتوفو والبروكوليني على الأطباق. رُشّ صلصة الفول السوداني فوق التوفو."])}))
R.append((6462700,{
"es":L("Calabacín empanizado con parmesano al horno","El calabacín empanizado de inspiración italiana es una guarnición crujiente y aprobada por los niños que no solo es deliciosa, sino también apta para la diabetes y más baja en carbohidratos.","6","1/2 taza",
["1 taza de pan molido","1/2 taza de queso parmesano (rallado, bajo en sodio)","1 cucharadita de orégano seco","1 cucharadita de ajo en polvo","1/8 cucharadita de sal","1/4 cucharadita de pimienta negra","2 huevos grandes (batidos)","2 calabacines medianos (cortados en rodajas)","1 rocío de aceite en aerosol antiadherente (de oliva)"],
["Precaliente el horno a 425 grados F.","En un tazón, combine el pan molido, el queso parmesano rallado, el orégano seco, el ajo en polvo, la sal y la pimienta negra.","Sumerja cada rodaja de calabacín en los huevos batidos, asegurándose de que queden bien cubiertas.","Cubra cada rodaja de calabacín pasada por huevo con la mezcla de pan molido, presionando las migas sobre el calabacín para que se adhieran.","Coloque las rodajas de calabacín empanizadas en una bandeja para hornear rociada con aceite de oliva en aerosol.","Rocíe ligeramente la parte superior de las rodajas de calabacín empanizadas con aceite de oliva en aerosol.","Hornee en el horno precalentado durante 20 minutos, o hasta que el calabacín esté tierno y el empanizado esté dorado.","Retire el calabacín del horno y pase a una fuente para servir."]),
"ar":L("كوسا مخبوزة مغطاة بفتات الخبز والبارميزان","الكوسا المغطاة بفتات الخبز المستوحاة من المطبخ الإيطالي طبق جانبي مقرمش ينال إعجاب الأطفال، وهو لذيذ ومناسب لمرضى السكري وأقل في الكربوهيدرات.","6","½ كوب",
["1 كوب فتات الخبز","½ كوب جبن بارميزان (مبشور، قليل الصوديوم)","1 ملعقة صغيرة أوريجانو مجفف","1 ملعقة صغيرة مسحوق الثوم","⅛ ملعقة صغيرة ملح","¼ ملعقة صغيرة فلفل أسود","2 بيضة كبيرة (مخفوقة)","2 حبة كوسا متوسطة (مقطعة إلى شرائح دائرية)","1 بخّة بخاخ طهي غير لاصق (بزيت الزيتون)"],
["سخّن الفرن مسبقًا إلى 425 درجة فهرنهايت (220° مئوية).","في وعاء، اخلط فتات الخبز وجبن البارميزان المبشور والأوريجانو المجفف ومسحوق الثوم والملح والفلفل الأسود.","اغمس كل شريحة كوسا في البيض المخفوق مع التأكد من تغطيتها جيدًا.","غطِّ كل شريحة كوسا مغموسة بالبيض بخليط فتات الخبز، مع الضغط على الفتات فوق الكوسا ليلتصق.","ضع شرائح الكوسا المغطاة بفتات الخبز على صينية خبز مرشوشة ببخاخ زيت الزيتون.","رُشّ وجه شرائح الكوسا المغطاة قليلًا ببخاخ زيت الزيتون.","اخبزها في الفرن المسخّن مسبقًا لمدة 20 دقيقة أو حتى تصبح الكوسا طرية ويتحمر الغطاء بلون ذهبي.","أخرج الكوسا من الفرن وانقلها إلى طبق التقديم."])}))
R.append((6464029,{
"es":L("Ensalada de pollo satay","Esta ensalada de pollo satay baja en grasa es una versión más ligera del clásico plato del sudeste asiático. Es apta para la diabetes gracias a la pechuga de pollo magra y a un aderezo cremoso estilo satay hecho con mantequilla de maní en polvo para reducir la grasa. Servida sobre una ensalada fresca y crujiente de lechuga romana, pepino y chalotes, es sabrosa, saciante y equilibrada para ayudarle a controlar la glucosa en la sangre (azúcar en la sangre).","4","2 tazas de ensalada y 4 onzas de pollo",
["1 cucharada de salsa de soya baja en sodio","1 cucharadita de curry en polvo mediano","1/4 cucharadita de comino molido","1 diente de ajo (rallado fino)","1 libra de pechugas de pollo sin hueso ni piel (cortadas en filetes delgados)","1/4 taza de mantequilla de maní en polvo (por ejemplo, PB2)","2 cucharadas de agua tibia (ajuste según la consistencia deseada)","1 cucharada de salsa de chile dulce","1 cucharada de jugo de limón verde","2 cogollos de lechuga romana (picados)","1/2 pepino (partido a lo largo por la mitad y en rodajas)","1 chalote pequeño (en rodajas finas)","1/4 taza de cilantro fresco (picado [opcional])","1/2 taza de granos de granada"],
["En un tazón, combine la salsa de soya, el curry en polvo, el comino y el ajo. Agregue las rebanadas de pollo, asegurándose de que queden bien cubiertas. Tape y refrigere por lo menos 1 hora, preferiblemente toda la noche.","En un tazón pequeño, mezcle la mantequilla de maní en polvo con el agua tibia hasta obtener una mezcla suave. Incorpore la salsa de chile dulce y el jugo de limón verde.","Engrase ligeramente un sartén antiadherente o una plancha acanalada y caliente a fuego medio. Cocine el pollo marinado de 5 a 6 minutos por lado, hasta que esté completamente cocido y dorado. Pase a un plato y déjelo reposar unos minutos antes de cortarlo.","En un tazón grande, combine la lechuga romana, el pepino, el chalote y el cilantro. Divida la ensalada entre cuatro platos. Cubra cada uno con el pollo y espolvoree con semillas de granada. Rocíe con el aderezo satay justo antes de servir."]),
"ar":L("سلطة دجاج ساتيه","سلطة دجاج الساتيه قليلة الدسم هذه نسخة أخف من الطبق الكلاسيكي في جنوب شرق آسيا. وهي مناسبة لمرضى السكري بفضل صدر الدجاج قليل الدهن وصلصة كريمية على طريقة الساتيه تعتمد على زبدة الفول السوداني البودرة لتقليل الدهون. تُقدَّم على سلطة منعشة ومقرمشة من الخس الروماني والخيار والبصل الأخضر الصغير (الإشالوت)، فهي غنية بالنكهة ومشبعة ومتوازنة لمساعدتك على التحكم في مستوى الغلوكوز في الدم (سكر الدم).","4","2 كوب سلطة و4 أونصات دجاج",
["1 ملعقة كبيرة صلصة صويا أقل صوديومًا","1 ملعقة صغيرة مسحوق الكاري المتوسط","¼ ملعقة صغيرة كمون مطحون","1 فص ثوم (مبشور ناعمًا)","1 رطل صدور دجاج بدون عظم وبدون جلد (مقطعة إلى شرائح رفيعة)","¼ كوب زبدة فول سوداني بودرة (مثل PB2)","2 ملعقة كبيرة ماء دافئ (عدّل الكمية حسب القوام المطلوب)","1 ملعقة كبيرة صلصة تشيلي حلوة","1 ملعقة كبيرة عصير ليمون أخضر","2 رأس قلوب الخس الروماني (مفرومة)","½ حبة خيار (مقطوعة طوليًا إلى نصفين ومقطعة شرائح)","1 حبة إشالوت صغيرة (مقطعة شرائح رفيعة)","¼ كوب كزبرة خضراء طازجة (مفرومة [اختياري])","½ كوب حبوب رمان"],
["في وعاء، اخلط صلصة الصويا ومسحوق الكاري والكمون والثوم. أضف شرائح الدجاج مع التأكد من تغطيتها جيدًا. غطِّه وضعه في الثلاجة لمدة ساعة على الأقل، ويفضل طوال الليل.","في وعاء صغير، اخلط زبدة الفول السوداني البودرة مع الماء الدافئ حتى تصبح ناعمة. أضف صلصة التشيلي الحلوة وعصير الليمون الأخضر وقلّب.","ادهن مقلاة غير لاصقة أو مقلاة شواء بقليل من الزيت وسخّنها على نار متوسطة. اطهِ الدجاج المتبّل لمدة 5 إلى 6 دقائق لكل جانب حتى ينضج تمامًا ويتحمر. انقله إلى طبق واتركه يرتاح بضع دقائق قبل تقطيعه.","في وعاء كبير، اخلط الخس الروماني والخيار والإشالوت والكزبرة الخضراء. وزّع السلطة على أربعة أطباق. ضع الدجاج فوق كل طبق ورشّ بحبوب الرمان. رُشّ صلصة الساتيه قبل التقديم مباشرة."])}))
R.append((6464139,{
"es":L("Camarones al limón (Gamberi al Limone)","La autora Amy Riolo dice: \"Todas las aguas que bordean Italia, desde el Adriático hasta los mares Jónico, Mediterráneo y Tirreno, contienen múltiples variedades de camarones, lo que hace que sean populares en todas partes. Si nunca ha preparado camarones, se sorprenderá de lo fácil que es. En mis clases de cocina de mariscos, a menudo les digo a los alumnos que, si antes les ha ido mal con los camarones, es porque hacen demasiado, no demasiado poco. La clave para preparar buenos camarones es elegir los más frescos posible y cocinarlos justo hasta que estén listos, ni un segundo más. En esta receta sirven camarones pequeños, medianos y jumbo, así que use con confianza los que estén más frescos\".","4","Aproximadamente 4 onzas de camarones",
["1 cucharada de aceite de oliva extra virgen","1 libra de camarones (pelados y desvenados)","1/2 cucharadita de sal kosher","1/4 cucharadita de pimienta negra (recién molida)","1/8 cucharadita de hojuelas de chile rojo triturado (al gusto)","2 cucharadas de jugo de limón (de 1 limón mediano)","1 cucharada de ralladura de limón (de 1 limón mediano)"],
["Caliente el aceite de oliva en un sartén grande a fuego medio-alto.","Cuando el aceite de oliva empiece a liberar su aroma, agregue los camarones, la sal, la pimienta negra y las hojuelas de chile rojo. Cocine los camarones de un lado solo hasta que la cola esté de un rosa brillante, aproximadamente 1 a 2 minutos.","Voltee los camarones y exprima el jugo de limón por encima. Cocine los camarones hasta que desaparezca todo el color gris y estén rosados y bien cocidos, aproximadamente 1 a 2 minutos más. En este punto, los camarones deben estar un poco más enroscados que cuando estaban crudos. Los camarones seguirán chisporroteando en el sartén.","Cuando estén completamente cocidos, pase los camarones a una fuente para servir, decore con la ralladura de limón y sirva de inmediato."]),
"ar":L("روبيان بالليمون (غامبيري آل ليموني)","تقول المؤلفة إيمي ريولو: \"جميع المسطحات المائية التي تحيط بإيطاليا، من الأدرياتيكي إلى الأيوني والمتوسط والتيراني، تضم أنواعًا متعددة من الروبيان، مما يجعله مشهورًا في كل مكان. إذا لم تحضّر الروبيان من قبل فستندهش من سهولته. في دروس طهي المأكولات البحرية التي أقدمها، أقول للطلاب كثيرًا إنهم إن كانوا قد أخفقوا في تحضير الروبيان في الماضي فذلك لأنهم يفعلون الكثير لا القليل. مفتاح تحضير روبيان جيد هو اختيار أطزج روبيان ممكن وطهيه حتى ينضج فقط، دون ثانية زيادة. يصلح الروبيان الصغير والعادي والجامبو في هذه الوصفة، فاستخدم ما هو أطزج بحرية\".","4","نحو 4 أونصات روبيان",
["1 ملعقة كبيرة زيت زيتون بكر ممتاز","1 رطل روبيان (مقشر ومنزوع العرق)","½ ملعقة صغيرة ملح كوشر","¼ ملعقة صغيرة فلفل أسود (مطحون طازجًا)","⅛ ملعقة صغيرة رقائق الفلفل الأحمر الحار المجروشة (حسب الرغبة)","2 ملعقة كبيرة عصير ليمون (من 1 ليمونة متوسطة)","1 ملعقة كبيرة قشر ليمون مبشور (من 1 ليمونة متوسطة)"],
["سخّن زيت الزيتون في مقلاة كبيرة على نار متوسطة إلى عالية.","عندما يبدأ زيت الزيتون بإطلاق رائحته، أضف الروبيان والملح والفلفل الأسود ورقائق الفلفل الأحمر المجروشة. اطهِ الروبيان من جانب واحد فقط حتى يصبح ذيل الروبيان وردي اللون الزاهي، نحو 1 إلى 2 دقيقة.","اقلب الروبيان واعصر عصير الليمون فوقه. اطهِ الروبيان حتى يختفي اللون الرمادي تمامًا ويصبح ورديًا ومطهوًا جيدًا، نحو 1 إلى 2 دقيقة إضافية. عندها يجب أن يكون الروبيان ملتفًّا بإحكام أكثر مما كان عليه وهو نيئ. سيستمر الروبيان في الأزيز في المقلاة.","عندما ينضج تمامًا، انقل الروبيان إلى طبق التقديم، وزيّنه بقشر الليمون المبشور، وقدّمه فورًا."])}))
R.append((6466152,{
"es":L("Crostini de ricotta y mermelada de moras","¿Necesita algo elegante? Esta receta de crostini se convertirá en su opción favorita de aperitivo. También sirve como refrigerio fácil después del trabajo o de la escuela. Para prepararlo no necesita realmente una baguette entera de un pie de largo; la receta funciona sorprendentemente bien con rebanadas de un pan tipo hoagie o submarino estándar, siempre que no esté ya abierto por la mitad.","6","2 crostini",
["1 pan hoagie o submarino integral entero","3/4 taza de queso ricotta semidescremado","1/4 taza de mermelada de moras endulzada con fruta","3/4 taza de moras frescas o congeladas descongeladas","1/8 cucharadita de sal marina"],
["Con un cuchillo para pan, recorte los extremos redondeados del pan. Corte el pan en 12 rebanadas de aproximadamente 1/2 pulgada de grosor cada una. Tueste las rebanadas de pan en una tostadora hasta que estén doradas.","Cubra cada rebanada con 1 cucharada del queso ricotta y luego con 1 cucharadita de la mermelada. Cubra de manera uniforme con las moras y luego espolvoree con la sal. Acomode en una fuente y sirva."]),
"ar":L("كروستيني الريكوتا ومربى التوت الأسود","هل تريد شيئًا أنيقًا؟ ستصبح وصفة الكروستيني هذه خيارك المفضل للمقبّلات. كما أنها تصلح كوجبة خفيفة سهلة بعد العمل أو بعد المدرسة. لتحضيرها لا تحتاج فعلًا إلى رغيف باغيت كامل بطول قدم؛ فالوصفة تنجح بشكل مدهش مع شرائح من رغيف الهوجي أو الساندويتش الصغير العادي، ما دام غير مشقوق مسبقًا.","6","2 كروستيني",
["1 رغيف هوجي أو ساندويتش صغير من القمح الكامل","¾ كوب جبن ريكوتا نصف منزوع الدسم","¼ كوب مربى التوت الأسود محلّى بالفاكهة","¾ كوب توت أسود طازج أو مجمد مذاب","⅛ ملعقة صغيرة ملح بحري"],
["باستخدام سكين الخبز، اقطع الطرفين المستديرين للرغيف. قطّع الرغيف إلى 12 شريحة بسمك نحو ½ بوصة لكل منها. حمّص شرائح الخبز في محمصة الخبز حتى تصبح ذهبية اللون.","ضع على كل شريحة 1 ملعقة كبيرة من جبن الريكوتا، ثم 1 ملعقة صغيرة من المربى. غطِّها بالتساوي بالتوت الأسود ثم رشّ الملح. رتّبها على طبق وقدّمها."])}))
R.append((6466239,{
"es":L("Tomates cherry salteados al estilo italiano","Haga de esta su nueva guarnición favorita para las noches entre semana. Es muy rápida, muy económica y puede convertir cualquier comida en algo especial. Puede servirlos con cuchara sobre arroz integral, usarlos como toque final sobre pollo a la parrilla o servirlos junto a una ensalada verde fresca. ¡Qué manera tan fácil de pasar de lo básico a un plato de restaurante!","4","1/4 taza",
["1 cucharada de aceite de oliva","1 envase (12 onzas) de tomates uva o cherry","2 dientes de ajo (en láminas finas)","2 cucharadas de vinagre balsámico","2 cucharaditas de sustituto de azúcar bajo en calorías"],
["En un sartén grande a fuego alto, caliente el aceite hasta que esté bien caliente. Saltee los tomates de 4 a 5 minutos, o hasta que la piel empiece a dorarse y a formar ampollas.","Agregue el ajo y cocine 1 minuto. Añada el vinagre balsámico y el sustituto de azúcar y siga cocinando de 1 a 2 minutos, o hasta que la mezcla empiece a espesar. Sirva caliente o a temperatura ambiente."]),
"ar":L("طماطم محمّرة على الطريقة الإيطالية","اجعل هذا الطبق الجانبي خيارك الجديد في أيام الأسبوع. فهو سريع جدًا ورخيص جدًا، ويمكنه أن يحوّل أي وجبة إلى وجبة مميزة. يمكنك وضعه بالملعقة فوق الأرز البني، أو جعله اللمسة الأخيرة على الدجاج المشوي، أو تقديمه بجانب سلطة خضراء طازجة. يا لها من طريقة سهلة للانتقال من البساطة إلى مستوى المطاعم!","4","¼ كوب",
["1 ملعقة كبيرة زيت زيتون","1 علبة (12 أونصة) طماطم عنبية أو كرزية","2 فص ثوم (مقطع شرائح رفيعة)","2 ملعقة كبيرة خل بلسمي","2 ملعقة صغيرة بديل سكر قليل السعرات"],
["في مقلاة كبيرة على نار عالية، سخّن الزيت حتى يسخن جيدًا. قلّب الطماطم لمدة 4 إلى 5 دقائق، أو حتى يبدأ جلدها بالتحمير والتنفّط.","أضف الثوم واطهِ لمدة دقيقة واحدة. أضف الخل البلسمي وبديل السكر وتابع الطهي لمدة 1 إلى 2 دقيقة، أو حتى يبدأ الخليط بالتكاثف. قدّمه ساخنًا أو بدرجة حرارة الغرفة."])}))
dump(2,R)
